test('fifteenth batch exposes dated loan difference without inventing asset totals',async({page},info)=>{await page.goto('/analysis/disclosures/');await page.getByLabel('Candidate or constituency').fill('Moirangthem Hemanta Singh');await page.locator('tbody th a').click();const panel=page.locator('.disclosure-field-review');await expect(panel).toContainText('₹64,50,000');await expect(panel).toContainText('₹7,06,84,000');await expect(panel).toContainText('no primary monetary total assigned');await panel.screenshot({path:info.outputPath('financial-hemanta-desktop.png')});await page.goto('/analysis/disclosures/');await page.getByLabel('Candidate or constituency').fill('Paonam Brojen Singh');await page.locator('tbody th a').click();await expect(panel).toContainText('₹0.39 difference remains unresolved');await expect(panel).toContainText('₹1,05,15,972.27');await expect(panel).toContainText('31/12/2021');await expect(panel).toContainText('5/1/2022');await expect(panel).toContainText('not converted to zero');await page.setViewportSize({width:390,height:844});await panel.screenshot({path:info.outputPath('financial-brojen-mobile.png')});expect(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)).toBe(false);});

