test('statewide evidence worklist searches sixty seats and preserves missingness and vacancy scopes',async({page},info)=>{await page.goto('/outlook/inputs/#seat-evidence-worklist');const panel=page.locator('#seat-evidence-worklist');const table=page.getByRole('region',{name:'Statewide constituency evidence worklist',exact:true});await expect(table.locator('tbody tr')).toHaveCount(60);await expect(panel).toContainText('not complete affidavit audits');await page.getByLabel('Find evidence constituency').fill('49');await expect(table.locator('tbody tr')).toHaveCount(1);await expect(table).toContainText('Listed vacant');await expect(table).toContainText('not Assembly winner');await table.locator('summary').click();await expect(table).toContainText('Complete verified 2027 nominee set: not indexed');await table.locator('summary').click();await expect(table).toContainText('effective affiliation date unverified');await expect(table.locator('a').first()).toHaveAttribute('href',/ac=49/);await page.getByLabel('Find evidence constituency').fill('');await page.getByLabel('Evidence review coverage').selectOption('deferred');await expect(table.locator('tbody tr')).toHaveCount(1);await expect(table).toContainText('source-location deferral');await page.getByLabel('Evidence review coverage').selectOption('none');await expect(table.locator('tbody tr').first()).toContainText('No selected candidate review');await panel.screenshot({path:info.outputPath('evidence-worklist-desktop.png')});await page.setViewportSize({width:390,height:844});await page.getByLabel('Find evidence constituency').fill('not-a-constituency');await expect(panel).toContainText('No matching constituency');await page.getByLabel('Find evidence constituency').fill('');await panel.screenshot({path:info.outputPath('evidence-worklist-mobile.png')});expect(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)).toBe(false);});

